## Bookings

### Create Specialist Booking Request Schema
```json
{
  "type": "object",
  "required": [
    "userId",
    "specialistId",
    "primaryConcern",
    "consultationMode",
    "bookingDate",
    "bookingTime"
  ],
  "properties": {
    "userId": {
      "type": "string",
      "minLength": 1
    },
    "dependentId": { "type": "string" },
    "specialistId": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{24}$",
      "description": "Invalid specialist ID format"
    },
    "primaryConcern": {
      "type": "string",
      "minLength": 1
    },
    "consultationMode": {
      "type": "string",
      "enum": ["chat", "call", "in-person"]
    },
    "bookingDate": {
      "type": "string",
      "pattern": "^\\d{8}$",
      "description": "Booking date must be in YYYYMMDD format (e.g., 20250215)"
    },
    "bookingTime": {
      "type": "string",
      "minLength": 1
    },
    "serviceAddress": {
      "type": "object",
      "properties": {
        "addressLine": {
          "type": "string",
          "minLength": 1
        },
        "city": {
          "type": "string",
          "minLength": 1
        },
        "pincode": {
          "type": "string",
          "minLength": 1
        },
        "state": { "type": "string" }
      },
      "required": ["addressLine", "city", "pincode"]
    },
    "documents": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["type", "url"],
        "properties": {
          "type": {
            "type": "string",
            "enum": ["report", "prescription", "other"]
          },
          "url": {
            "type": "string",
            "format": "uri"
          },
          "fileName": { "type": "string" }
        }
      }
    },
    "notes": { "type": "string" }
  },
  "additionalProperties": false
}
```

