import {
  CUSTOMER_DIAGNOSTICS_PROGRESS_STATUSES,
  CustomerDiagnosticsProgress,
  CustomerDiagnosticsHistoryPage,
  ExternalBookingListQuery,
  IExternalBooking,
} from '@/modules/externalBookings/types';
