  { _id: false }
);

const userSchema = new Schema<IUser>(
  {
    // Authentication & Basic Info
    email: {
      type: String,
      sparse: true,
      index: true,
      trim: true,
      lowercase: true,
    },
    corporateEmail: {
      type: String,
      sparse: true,
      unique: true,
      index: true,
      trim: true,
      lowercase: true,
    },
    phone: {
      type: String,
      sparse: true,
      index: true,
      trim: true,
    },
    userType: {
      type: String,
      required: true,
      enum: ['user'],
      default: 'user',
      index: true,
    },
    name: {
      type: String,
      trim: true,
      index: true,
    },
    age: {
      type: Number,
      min: 0,
      max: 150,
    },
    profilePictureUrl: {
      type: String,
      trim: true,
    },

