    dateOfBirth: {
      type: String,
      match: /^\d{8}$/, // YYYYMMDD format
    },
    gender: {
      type: String,
      enum: ['Male', 'Female', 'Other'],
      trim: true,
    },
    bloodGroup: {
      type: String,
      enum: ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'],
      trim: true,
    },
    height: {
      type: Number,
      min: 0,
      max: 300, // in cm
    },
    weight: {
      type: Number,
      min: 0,
      max: 500, // in kg
    },
    emergencyContact: {
      type: emergencyContactSchema,
    },
    // Address fields
    address: {
      type: String,
      trim: true,
    },
    latitude: {
      type: Number,
      min: -90,
      max: 90,
    },
    longitude: {
      type: Number,
      min: -180,
      max: 180,
    },
    city: {
      type: String,
      trim: true,
      index: true,
    },
    state: {
      type: String,
      trim: true,
      index: true,
    },
    pincode: {
      type: String,
      trim: true,
    },
    country: {
      type: String,
      trim: true,
      default: 'India',
    },
    // Corporate association
    corporateId: {
      type: String,
      index: true,
    },
    referralCode: {
      type: String,
      trim: true,
      uppercase: true,
      sparse: true,
      unique: true,
      index: true,
    },
    referredByUserId: {
      type: String,
      index: true,
    },

    // Status fields
    isActive: {
      type: Boolean,
      default: true,
      index: true,
    },
    isVerified: {
      type: Boolean,
      default: false,
      index: true,
    },
    isCorporateEmailVerified: {
      type: Boolean,
      default: false,
      index: true,
    },
    createdSource: {
      type: String,
      enum: ['self_signup', 'pharmacy_app'],
      default: 'self_signup',
      index: true,
    },
    createdByRole: {
      type: String,
      trim: true,
    },
    createdById: {
      type: String,
      index: true,
    },
    otpVerified: {
      type: Boolean,
      default: false,
      index: true,
    },
    linkedPharmacyId: {
      type: String,
      index: true,
    },
  },
  {
    timestamps: true,
  }
);

// Compound indexes for efficient queries
userSchema.index({ phone: 1, userType: 1 });
userSchema.index({ email: 1, userType: 1 });
userSchema.index({ corporateEmail: 1, userType: 1 });
userSchema.index({ corporateId: 1, userType: 1 });
userSchema.index({ corporateId: 1, isActive: 1 });
userSchema.index({ userType: 1, isActive: 1 });
userSchema.index({ userType: 1, isVerified: 1 });
userSchema.index({ name: 'text' }); // Text search index

const UserModel: Model<IUser> = model<IUser>('User', userSchema);

export default UserModel;

import { Service } from 'typedi';
import { Model } from 'mongoose';
import UserModel from '@/modules/user/model';
import { IUser } from '@/modules/user/types';
import { BaseRepository } from '@/modules/common/repository';

@Service()
export class UserRepository extends BaseRepository<IUser> {
  constructor() {
    super(UserModel as Model<IUser>);
  }

  findByPhone = async (phone: string, userType: string): Promise<IUser | null> => {
    return this.findOne({ phone, userType });
  };

  findByEmail = async (email: string, userType: string): Promise<IUser | null> => {
    return this.findOne({ email, userType });
  };

  findByCorporateEmail = async (
    corporateEmail: string,
    userType: string
  ): Promise<IUser | null> => {
    return this.findOne({ corporateEmail, userType });
  };

  findByPhoneOrEmail = async (
    phoneOrEmail: { phone?: string; email?: string },
    userType: string
  ): Promise<IUser | null> => {
    const query: any = { userType };
    if (phoneOrEmail.phone) {
      query.phone = phoneOrEmail.phone;
    } else if (phoneOrEmail.email) {
      query.email = phoneOrEmail.email;
    }
    return this.findOne(query);
  };

  findByAnyEmail = async (
    email: string,
    userType: string,
    excludeUserId?: string
  ): Promise<IUser | null> => {
    return this.findOne({
      userType,
      ...(excludeUserId ? { _id: { $ne: excludeUserId } } : {}),
      $or: [{ email }, { corporateEmail: email }],
    } as any);
  };

  findByReferralCode = async (referralCode: string): Promise<IUser | null> => {
    return this.findOne({ referralCode: referralCode.toUpperCase() });
  };
}

